package net.civeira.phylax.feature.identity.userpurposeconsent.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userpurposeconsent.domain.UserPurposeConsent;
import net.civeira.phylax.feature.identity.userpurposeconsent.domain.valueobject.GrantedVO;

class GrantedValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of granted of user purpose consent")
  void test_granted_value_holder_assign_plain_value() {
    Object holder = new Object();
    GrantedValueHolder<Object> value = new GrantedValueHolder<>(holder);
    Assertions.assertSame(holder, value.granted(true), "Setters must return the holder");
    Assertions.assertTrue(value.getGrantedValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(true, value.getGranted().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of granted of user purpose consent")
  void test_granted_value_holder_assign_value_object() {
    Object holder = new Object();
    GrantedValueHolder<Object> value = new GrantedValueHolder<>(holder);
    GrantedVO vo = GrantedVO.from(true);
    Assertions.assertFalse(value.getGrantedValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.granted(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getGrantedValue().orElseThrow());
    Assertions.assertSame(holder, value.granted(Optional.empty()));
    Assertions.assertFalse(value.getGrantedValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.granted(Optional.of(vo)));
    Assertions.assertSame(vo, value.getGrantedValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of granted of user purpose consent against the original")
  void test_granted_value_holder_read() {
    Object holder = new Object();
    GrantedValueHolder<Object> value = new GrantedValueHolder<>(holder);
    GrantedVO vo = GrantedVO.from(true);
    GrantedVO other = GrantedVO.from(true);
    UserPurposeConsent original = Mockito.mock(UserPurposeConsent.class);
    Mockito.when(original.getGrantedValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readGranted(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readGranted(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.granted(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readGranted(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readGranted(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of granted of user purpose consent")
  void test_granted_value_holder_unset() {
    Object holder = new Object();
    GrantedValueHolder<Object> value = new GrantedValueHolder<>(holder);
    GrantedVO vo = GrantedVO.from(true);
    value.granted(vo);
    Assertions.assertSame(holder, value.unsetGrantedIfMatches("granted_other"));
    Assertions.assertTrue(value.getGrantedValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetGrantedIfMatches("granted"));
    Assertions.assertFalse(value.getGrantedValue().isPresent(),
        "The field name must clear the value");
    value.granted(vo);
    Assertions.assertSame(holder, value.unsetGranted());
    Assertions.assertFalse(value.getGrantedValue().isPresent(), "Unset must clear the value");
  }
}
